    ['「げんきですか」と きく いいかたは？','How are you?',['What is your name?','Good night.','See you.'],'げんきかどうかは How are you? と きくよ。']];
    Q.push(()=>{const it=G[this.rand(0,G.length-1)];return mc(it[0],it[1],it[2],it[3],true);});
