    if(stage>=5){const R=[['How are you?','I am fine.',['Good night.','My name is Ken.','Thank you.']],['What is your name?','My name is Ken.',['I am ten.','Good morning.','I like blue.']],['What color do you like?','I like blue.',['I am fine.','See you.','It is a dog.']]];Q.push(()=>{const it=R[this.rand(0,R.length-1)];return mc('しつもん「'+it[0]+'」に あう こたえは？',it[1],it[2],it[0]+' には '+it[1]+' と こたえるよ。',true);});}
    const q=Q[this.rand(0,Q.length-1)]();q.difficulty=stage;return q;}
